        seed::localized_response("general_plan_repository_planned", language)
            .unwrap_or_default()
            .replace(TARGET_PLACEHOLDER, &self.target)
            .replace("{plan_path}", PLAN_PATH)
            .replace(
                BODY_PLACEHOLDER,
                &crate::issue_report::fenced_block(
                    crate::issue_report::LINO_FENCE_LANGUAGE,
                    &self.links_notation(),
